            val actualInsertionIndex = invertedInsertionIndex.inv() // same as -(invertedInsertionIndex + 1)
            assertPrints(actualInsertionIndex, "3")

            list.add(actualInsertionIndex, 'd')
            assertPrints(list, "[a, b, c, d, e]")
