            when (currentValue % 2) {
                0L -> currentValue / 2L
                else -> 3 * currentValue + 1
            }
        }
        assertPrints(a.load(), "22")
    }

    @Sample
    fun updateAndFetch() {
        val a = AtomicLong(7L)
        val updatedValue = a.updateAndFetch { currentValue ->
            when (currentValue % 2) {
                0L -> currentValue / 2
                else -> 3 * currentValue + 1
            }
        }
        assertPrints(updatedValue, "22")
        assertPrints(a.load(), "22")
    }

    @Sample
    fun fetchAndUpdate() {
        val a = AtomicLong(7L)
        val oldValue = a.fetchAndUpdate { currentValue ->
            when (currentValue % 2) {
                0L -> currentValue / 2
                else -> 3 * currentValue + 1
            }
        }
        assertPrints(oldValue, "7")
        assertPrints(a.load(), "22")
    }
}

@OptIn(ExperimentalAtomicApi::class)
class AtomicBoolean {
    @Sample
