    assertTrue((atan(1.0f) - PI.toFloat() / 4).absoluteValue < epsilon)
    // atan(-1.0) = -π/4
    assertTrue((atan(-1.0f) - (-PI.toFloat() / 4)).absoluteValue < epsilon)
    // atan(tan(x)) = x
    assertTrue((atan(tan(0.25f)) - 0.25f).absoluteValue < epsilon)

