        max = 10
        assertPrints(max, "10")
    }

    @Sample
    fun observableDelegate() {
        var observed = false
        var max: Int by Delegates.observable(0) { property, oldValue, newValue ->
            observed = true
        }

        assertPrints(max, "0")
        assertFalse(observed)

        max = 10
        assertPrints(max, "10")
        assertTrue(observed)
    }
}

