        assertFailsWith<NumberFormatException> { "9223372036854775808".toLong() }
        // 'a' is not a digit
        assertFailsWith<NumberFormatException> { "-1a".toLong() }
        // underscore
        assertFailsWith<NumberFormatException> { "1_000".toLong() }
